<style scoped lang="scss" src="./search-field.scss"></style>
<style scoped lang="scss" src="./search-field-gms.scss"></style>
<style scoped lang="scss" src="./search-field-gms-customize.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon.vue";
import { IconShape } from "../icon/icon.constants";
import {
  SearchFieldMode,
  SearchFieldModeValues
} from "./search-field.constants";
import { has } from "../../util/has";

const modeToClass = {
  [SearchFieldMode.REGULAR]: "",
  [SearchFieldMode.GMS]: "SearchField_GMS",
  [SearchFieldMode.GMS_CUSTOMIZE]: "SearchField_GMS_CUSTOMIZE"
};

/**
 * This is a simple input formatted to look like a search field.
 */
@Component({
  components: {
    Icon
  }
})
export default class SearchField extends Vue {
  @Prop({ type: String, default: "" }) defaultValue;
  @Prop({ type: Boolean, default: false }) readOnly;
  @Prop({ type: String, default: "" }) placeholder;
  @Prop({
    type: String,
    default: SearchFieldMode.NORMAL,
    validator: has(SearchFieldModeValues)
  })
  mode;

  focused = false;
  hovered = false;
  value = "";
  error = "";
  multiline = false;
  isPassword = false;
  label = "";
  decal = {
    shape: IconShape.SEARCH,
    size: 16
  };

  mounted() {
    this.value = this.defaultValue;
    this.$emit("input", this.defaultValue);
  }

  get currentState() {
    return {
      focused: this.focused,
      hovered: this.hovered,
      value: this.value,
      error: this.error
    };
  }

  get modeClass() {
    return modeToClass[this.mode];
  }

  get IconShape() {
    return IconShape;
  }

  get SearchFieldMode() {
    return SearchFieldMode;
  }

  get stateClass() {
    if (this.focused) return "SearchField--focus";
    if (this.hovered) return "SearchField--hovered";
    return "";
  }

  get filledClass() {
    if (this.value) return "SearchField--filled";
    return "SearchField--empty";
  }

  handleChange() {
    this.value = this.$refs.inputField.value;
    /**
     * Change input event. Fires when the value of this field changes and
     * proivides the current value.
     *
     * @event input
     */
    this.$emit("input", this.value);
  }

  handleFocus() {
    this.focused = true;
  }

  handleBlur() {
    this.focused = false;
  }

  handleOver() {
    this.hovered = true;
  }

  handleOut() {
    this.hovered = false;
  }
}
</script>

<template>
  <div
    :class="[
      'SearchField',
      filledClass,
      stateClass,
      error ? 'SearchField--error' : '',
      !label ? 'SearchField--single-row' : '',
      readOnly ? 'SearchField--disabled' : '',
      modeClass
    ]"
    ref="container"
    @mouseover="handleOver"
    @mouseout="handleOut"
  >
    <div v-if="decal !== void 0" class="SearchField__Decal">
      <Icon
        v-if="mode === SearchFieldMode.GMS"
        :shape="IconShape.SEARCH_2"
        :size="20"
        :color="'#2356f6'"
      />
      <Icon
        v-else-if="mode === SearchFieldMode.GMS_CUSTOMIZE"
        :shape="IconShape.SEARCH_2"
        :size="18"
        :color="'#656677'"
      />
      <Icon v-else :shape="decal.shape" :size="decal.size" />
    </div>
    <div
      :class="[
        'SearchField__Left',
        decal !== void 0 ? 'SearchField--decal' : ''
      ]"
    >
      <div
        v-if="label"
        :class="[
          'SearchField__Label',
          error ? 'SearchField__Label SearchField--error' : ''
        ]"
      >
        {{ label }}
      </div>
      <textarea
        v-if="multiline"
        :readOnly="readOnly"
        spellCheck="false"
        autoCorrect="false"
        ref="inputField"
        :value="value"
        :placeholder="placeholder"
        @input="handleChange"
        @focus="handleFocus"
        @blur="handleBlur"
      />
      <input
        v-else
        :readOnly="readOnly"
        spellCheck="false"
        autoCorrect="false"
        ref="inputField"
        :type="isPassword ? 'password' : multiline ? 'textarea' : 'text'"
        :value="value"
        :placeholder="placeholder"
        @input="handleChange"
        @focus="handleFocus"
        @blur="handleBlur"
      />
      <div v-if="error" :class="['SearchField__Error', 'SearchField--error']">
        {{ typeof error === "string" ? error : this.error }}
      </div>
    </div>
  </div>
</template>
